from torch_geometric.nn import GATConv
class GAT(nn.Module):
    def __init__(self, in_channels, hidden, out_channels):
        super().__init__()
        self.g1=GATConv(in_channels, hidden, heads=4)
        self.g2=GATConv(hidden*4, out_channels, heads=1, concat=False)
    def forward(self, x, edges):
        return self.g2(self.g1(x,edges).elu(),edges)
