class Sage(nn.Module):
    def __init__(self, n_in, n_hidden, n_out):
        super().__init__()
        self.layers=nn.ModuleList([SAGEConv(n_in,n_hidden), SAGEConv(n_hidden,n_out)])
    def forward(self,x,edges):
        x=self.layers[0](x,edges).relu()
        return self.layers[1](x,edges)
