import torch
from torch import nn
# Bloque causal simple; un TCN completo añade residualidad y varios bloques.
class CausalConv(nn.Module):
    def __init__(self,n_in,n_out,kernel=3,dilation=2):
        super().__init__()
        self.pad=(kernel-1)*dilation
        self.conv=nn.Conv1d(n_in,n_out,kernel,dilation=dilation,padding=self.pad)
    def forward(self,x):
        return self.conv(x)[...,:-self.pad] if self.pad else self.conv(x)
