from torch import nn
class DeepSets(nn.Module):
    def __init__(self):
        super().__init__()
        self.phi=nn.Sequential(nn.Linear(6,32),nn.ReLU())
        self.rho=nn.Sequential(nn.Linear(32,16),nn.ReLU(),nn.Linear(16,1))
    def forward(self,x):
        return self.rho(self.phi(x).sum(dim=1))
